-- 14 Nov 2026 — Guest Hub «مركز الضيوف», session H4: the knowledge base (docs/guest-hub/GUEST-HUB-SPEC.md v0.6 §13 row
-- H4, §1.7, §3.2, §3.4 «Knowledge», §4.1, §4.4, §4.6, §4.7, §5.4, §5.5, §7.5; DECISIONS.md 2026-11-14 «Guest Hub H4 —
-- the knowledge base»). GENERATED by scripts/hub-knowledge-migration.mjs from scripts/hub-knowledge-migration.src.sql,
-- docs/guest-hub/topics.json and docs/guest-hub/knowledge-seed.json — hub-seed-check proves the seed blocks equal the files.
--
-- Nothing here calls a model, talks to a guest or switches anything on. It creates:
--   1. hub_units.knowledge_hidden — the rooftop restaurant's knowledge exclusion (true for the rooftop unit only; Ahmed,
--      13 Nov 2026): a card tagged with such a unit is never retrieved on any number. NOT the hidden status: the lobby
--      café's unit is hidden only because its channel is postponed, and its facts (tagged airport-road) stay answerable.
--   2. hub_topics (the taxonomy, seeded from topics.json: 56 topics, 9 always handed off; faq_keys = the published FAQ
--      questions each topic reads) and hub_knowledge_cards (draft / published / archived; live written only by
--      hub_knowledge_publish; both languages, a source and its date required; internal.copy_problems + the shared
--      forbidden list in both languages). Seeded: the 37 cards of knowledge-seed.json as PUBLISHED, verified by the system
--      admin (the one active role-admin; none in an empty database). The two Wi-Fi cards are NOT here (the repository is
--      public): they are loaded on production by a one-off statement.
--   3. «لم أعرف الإجابة»: hub_mark_unanswered (H3) now keeps the question's excerpt (guest text, ≤ 300, 12 months) and
--      groups it with an open entry of the same topic and close wording (cluster_id = the first entry, times_asked its
--      count); hub_unanswered_topic_set, hub_unanswered_resolve (to a card, a FAQ draft in «الأسئلة الشائعة», both, or
--      dismissed — every entry of the cluster), hub_unanswered_list (the excerpt only through the unit scope).
--   4. RPCs: hub_card_save, hub_card_archive, hub_card_restore, hub_knowledge_publish (never undoable; the test-lab gate
--      of H6 hooks into internal.hub_knowledge_gate), hub_knowledge_faq, hub_service_prices, hub_expiring; the engine's read
--      hub_knowledge_for (service role only).
--   5. The expiry alerts: pg_cron hub-expiry daily 05:00 UTC (08:00 Riyadh) → hub_expiry_tick: one hub_alerts row per card
--      ending within hub_card_expiry_alert_days and per offer ending within hub_offer_expiry_alert_days; when a new one
--      appears, wa-automation (hub-expiry) claims the list and sends ONE email to the active admins.
--   6. hub_retention also clears the excerpts of «لم أعرف الإجابة» after hub_retention_months.
-- Changes to existing objects: hub_units (+ knowledge_hidden), internal.audit (copied from 20261113100000 with the
-- knowledge tables added), hub_alerts' one-open index (+ the item), hub_mark_unanswered and hub_retention (replaced).

select set_config('app.actor', 'migration', true);

-- ───────────────────────────────────────────── 1. the rooftop's knowledge exclusion ─────────────────────────────────────────────

alter table public.hub_units add column knowledge_hidden boolean not null default false;
comment on column public.hub_units.knowledge_hidden is 'Guest Hub H4 (Ahmed, 13 Nov 2026): this unit''s knowledge is excluded from every reply on every number (the rooftop restaurant until its opening). Not the hidden status.';
update public.hub_units set knowledge_hidden = true where key = 'rooftop';

-- ───────────────────────────────────────────── 2. tables ─────────────────────────────────────────────

create table public.hub_topics (
  key text primary key check (key ~ '^[a-z0-9_]{2,60}$'),
  label_ar text not null check (char_length(btrim(label_ar)) between 2 and 80),
  label_en text not null check (char_length(btrim(label_en)) between 2 and 80),
  parent_key text references public.hub_topics (key) on update cascade,
  -- always to the team, whatever a card says (complaint, compensation, deposit …)
  always_handoff boolean not null default false,
  status text not null default 'active' check (status in ('active', 'proposed', 'archived')),
  created_from text not null default 'seed' check (created_from in ('seed', 'queue')),
  -- the published FAQ questions (faq_items.key) this topic reads — the FAQ is read live, never copied (spec §4.6)
  faq_keys text[] not null default '{}',
  sort integer not null default 0,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint hub_topics_not_own_parent check (parent_key is distinct from key)
);
comment on table public.hub_topics is '«مركز الضيوف» topics (spec §4.7): the taxonomy every guest message is tagged with; seeded from docs/guest-hub/topics.json (13 Nov 2026). faq_keys: the FAQ questions each topic reads.';
create trigger hub_topics_touch before update on public.hub_topics for each row execute function internal.stamp();

create table public.hub_knowledge_cards (
  id uuid primary key default gen_random_uuid(),
  -- the card's name in the seed and the test bank (k-…); fixed once published
  key text not null unique check (key ~ '^k-[a-z0-9]+(-[a-z0-9]+)*$' and char_length(key) <= 60),
  -- the units it is about: empty = every unit; a card tagged with a unit is read only on that unit's number(s) (and a
  -- dining unit reads its branch's cards); a card tagged with a knowledge_hidden unit is never read
  unit_keys text[] not null default '{}',
  topic_keys text[] not null default '{}',
  title_ar text not null default '' check (char_length(title_ar) <= 120),
  title_en text not null default '' check (char_length(title_en) <= 120),
  text_ar text not null default '' check (char_length(text_ar) <= 1200),
  text_en text not null default '' check (char_length(text_en) <= 1200),
  -- where the fact comes from, as written there («أحمد، 30 أكتوبر 2026» / «branches.json» / «قرار 8 أكتوبر 2026»)
  source text not null default '' check (char_length(source) <= 300),
  source_date date,
  verified_by uuid references auth.users (id) on delete set null,
  verified_at timestamptz,
  -- null = no expiry; a card is out of every reply after this Riyadh date
  expires_on date,
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  -- what the engine reads — written only by hub_knowledge_publish
  live jsonb,
  published_at timestamptz,
  published_by uuid references auth.users (id) on delete set null,
  first_published_at timestamptz,
  archived_at timestamptz,
  archived_by uuid references auth.users (id) on delete set null,
  faq_item_id uuid references public.faq_items (id) on delete set null,
  sort integer not null default 0,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users (id) on delete set null,
  updated_by uuid references auth.users (id) on delete set null,
  constraint hub_cards_published_live check (status <> 'published' or live is not null)
);
comment on table public.hub_knowledge_cards is '«مركز الضيوف» knowledge cards (spec §4.6): short facts in both languages with a source, its date and who verified it; live = what the engine reads (hub_knowledge_publish only). Never a room rate, a fee or a guest''s words.';
create trigger hub_knowledge_cards_touch before update on public.hub_knowledge_cards for each row execute function internal.stamp();
create index hub_knowledge_cards_topics on public.hub_knowledge_cards using gin (topic_keys);

-- one open alert per kind, unit and ITEM (a card or an offer) — the expiry alerts are one row each (H4)
drop index public.hub_alerts_one_open;
create unique index hub_alerts_one_open on public.hub_alerts
  (kind, coalesce(unit_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(payload ->> 'item', '')) where acknowledged_at is null;

-- ───────────────────────────────────────────── 3. the checks ─────────────────────────────────────────────

-- the shared forbidden list (spec §2.4.2 rule 3): the strings qa.py refuses anywhere (CLAUDE.md §11, as review_problems),
-- the rooftop restaurant's name while its knowledge is hidden, the deposit words (Ahmed, 8 Oct 2026) and the plural
-- address forms (Ahmed, 4 Nov 2026). The guard of H5 reads this same function.
create function internal.hub_forbidden_terms() returns text[]
language sql immutable set search_path = '' as $$
  select array['شقق مخدومة', 'شقة مخدومة', 'serviced apartment', 'armada café', 'armada cafe', 'خدمة الغرف', 'room service', 'مكواة',
               'إسرائيل', 'israel', 'نادي أرمادا', 'armada residence club', 'armada club', 'اياب', '24 ساعة قبل الوصول',
               '24 ساعة قبل موعد الوصول', '24 hours before arrival', 'نفس يوم الوصول', 'same-day cancellation', 'unsplash', 'lorem ipsum',
               'لاريو', 'lario', 'عربون', 'تأمين', 'deposit', 'يمكنكم', 'تواصلوا', 'احجزوا', 'راسلونا']
$$;

-- the property's own numbers (content/contact.json: the two branches, sales, the café) — a card may give them (Ahmed,
-- 13 Nov 2026: the sales and café numbers are given when a guest asks); any other typed phone number stays refused.
-- hub-seed-check proves this list = contact.json.
create function internal.hub_known_phones() returns text[]
language sql immutable set search_path = '' as $$
  select array['966536622277', '966536663030', '966536622288', '966533798590']
$$;

-- a card's text with the property's own numbers taken out (in any spacing, +966 or 05…) — for copy_problems' phone rule
create function internal.hub_without_known_phones(p text) returns text
language plpgsql immutable set search_path = '' as $$
declare
  v text := coalesce(p, '');
  d text;
begin
  foreach d in array internal.hub_known_phones() loop
    v := regexp_replace(v, '\+?' || regexp_replace(d, '([0-9])', '\1[\s-]?', 'g'), ' هاتف ', 'g');
    v := regexp_replace(v, '0' || regexp_replace(substr(d, 4), '([0-9])', '\1[\s-]?', 'g'), ' هاتف ', 'g');
  end loop;
  return v;
end;
$$;

create function internal.hub_card_snapshot(c public.hub_knowledge_cards) returns jsonb
language sql immutable set search_path = '' as $$
  select jsonb_build_object('key', c.key, 'unit_keys', to_jsonb(c.unit_keys), 'topic_keys', to_jsonb(c.topic_keys),
                            'title_ar', c.title_ar, 'title_en', c.title_en, 'text_ar', c.text_ar, 'text_en', c.text_en,
                            'source', c.source, 'source_date', c.source_date, 'expires_on', c.expires_on, 'sort', c.sort)
$$;

create function internal.hub_card_pending(c public.hub_knowledge_cards) returns boolean
language sql immutable set search_path = '' as $$
  select c.status <> 'archived' and c.live is distinct from internal.hub_card_snapshot(c)
$$;

-- what blocks publishing a card: { missing: [{part: title | text | meta, code, …}] }
create function internal.hub_card_check(c public.hub_knowledge_cards) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v jsonb := '[]'::jsonb;
  l text;
  t text;
  v_term text;
begin
  v := v || coalesce((select jsonb_agg(jsonb_build_object('part', 'title') || e) from jsonb_array_elements(internal.copy_problems(c.title_ar, c.title_en, 120)) e), '[]'::jsonb);
  v := v || coalesce((select jsonb_agg(jsonb_build_object('part', 'text') || e)
                        from jsonb_array_elements(internal.copy_problems(internal.hub_without_known_phones(c.text_ar), internal.hub_without_known_phones(c.text_en), 1200)) e
                       where e ->> 'code' not in ('too_long')), '[]'::jsonb);
  -- copy_problems' length is measured on the text as written (the numbers taken out would shorten it)
  foreach l in array array['ar', 'en'] loop
    t := case l when 'ar' then c.text_ar else c.text_en end;
    if char_length(t) > 1200 then v := v || jsonb_build_object('part', 'text', 'code', 'too_long', 'lang', l, 'max', 1200); end if;
    t := lower(case l when 'ar' then c.title_ar || ' ' || c.text_ar else c.title_en || ' ' || c.text_en end);
    foreach v_term in array internal.hub_forbidden_terms() loop
      -- the copy_problems list already reports its own terms
      if strpos(t, v_term) > 0 and v_term not in ('شقق مخدومة', 'شقة مخدومة', 'serviced apartment', 'armada café', 'armada cafe', 'خدمة الغرف', 'room service') then
        v := v || jsonb_build_object('part', 'text', 'code', 'forbidden_term', 'lang', l, 'term', v_term);
      end if;
    end loop;
  end loop;
  if btrim(c.source) = '' then v := v || jsonb_build_object('part', 'meta', 'code', 'source_required'); end if;
  if c.source_date is null then v := v || jsonb_build_object('part', 'meta', 'code', 'source_date_required'); end if;
  if cardinality(c.topic_keys) = 0 then v := v || jsonb_build_object('part', 'meta', 'code', 'topic_required'); end if;
  if exists (select 1 from unnest(c.topic_keys) k where not exists (select 1 from public.hub_topics x where x.key = k and x.status <> 'archived')) then
    v := v || jsonb_build_object('part', 'meta', 'code', 'topic_unknown');
  end if;
  if exists (select 1 from unnest(c.unit_keys) k where not exists (select 1 from public.hub_units u where u.key = k)) then
    v := v || jsonb_build_object('part', 'meta', 'code', 'unit_unknown');
  end if;
  if c.expires_on is not null and c.source_date is not null and c.expires_on < c.source_date then
    v := v || jsonb_build_object('part', 'meta', 'code', 'expiry_before_source');
  end if;
  return jsonb_build_object('missing', v);
end;
$$;

create function internal.hub_card_get(p_id uuid, p_level public.perm_level) returns public.hub_knowledge_cards
language plpgsql security definer set search_path = '' as $$
declare c public.hub_knowledge_cards;
begin
  if not internal.can('knowledge', p_level) then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into c from public.hub_knowledge_cards where id = p_id for update;
  if c.id is null or (c.is_test and not internal.is_admin()) then raise exception 'not allowed' using errcode = '42501'; end if;
  return c;
end;
$$;

-- the Riyadh day (expiry and alerts are Riyadh dates)
create function internal.riyadh_today(p_now timestamptz default now()) returns date
language sql stable set search_path = '' as $$ select (p_now at time zone 'Asia/Riyadh')::date $$;

-- a SAR amount in a guest sentence — rules.ts sarText, the same forms: «20 ريالًا», «200 ريال», «3 ريالات» / "SAR 20"
create function internal.hub_sar_text(p numeric, p_lang text) returns text
language plpgsql immutable set search_path = '' as $$
declare
  v_whole boolean := round(p * 100) % 100 = 0;
  v_num text := case when round(p * 100) % 100 = 0 then round(p)::bigint::text else to_char(p, 'FM9999999990.00') end;
  n bigint := round(p)::bigint;
  k integer := (round(p)::bigint % 100)::integer;
begin
  if p is null then return null; end if;
  if p_lang = 'en' then return 'SAR ' || v_num; end if;
  return v_num || ' ' || case when not v_whole then 'ريال' when k between 3 and 10 then 'ريالات' when k = 0 or (k <= 2 and n > 100) then 'ريال' else 'ريالًا' end;
end;
$$;

-- a published FAQ answer as the site shows it: {breakfast} / {extra_bed} filled from Settings (site_fees)
create function internal.hub_fill_fees(p text, p_lang text) returns text
language sql stable security definer set search_path = '' as $$
  select replace(replace(coalesce(p, ''),
    '{breakfast}', coalesce(internal.hub_sar_text((public.site_fees() ->> 'breakfast_adult')::numeric, p_lang), '{breakfast}')),
    '{extra_bed}', coalesce(internal.hub_sar_text((public.site_fees() ->> 'extra_bed_per_night')::numeric, p_lang), '{extra_bed}'))
$$;

-- ───────────────────────────────────────────── 4. RLS and the library ─────────────────────────────────────────────

alter table public.hub_topics enable row level security;
alter table public.hub_knowledge_cards enable row level security;
revoke all on public.hub_topics, public.hub_knowledge_cards from public, anon, authenticated;
grant select on public.hub_topics, public.hub_knowledge_cards to authenticated;
grant all on public.hub_topics, public.hub_knowledge_cards to service_role;
create policy hub_topics_read on public.hub_topics for select to authenticated
  using ((internal.can('knowledge', 'view') or internal.can('inbox', 'view') or internal.can('radar', 'view') or internal.can('assistant', 'view'))
         and (not is_test or internal.is_admin()));
create policy hub_knowledge_cards_read on public.hub_knowledge_cards for select to authenticated
  using (internal.can('knowledge', 'view') and (not is_test or internal.is_admin()));

create view public.hub_cards_library with (security_invoker = true) as
  select c.*, internal.hub_card_pending(c) as pending, internal.hub_card_check(c) as "check",
         case when c.status = 'archived' then 'archived'
              when c.live is null then 'draft'
              when (c.live ->> 'expires_on') is not null and (c.live ->> 'expires_on')::date < internal.riyadh_today() then 'expired'
              else 'published' end as state,
         (select s.full_name from public.staff s where s.user_id = c.verified_by) as verified_by_name
    from public.hub_knowledge_cards c;
comment on view public.hub_cards_library is 'hub_knowledge_cards + pending + check + state (draft | published | expired | archived) + the verifier''s name. RLS of the cards applies (security invoker).';
revoke all on public.hub_cards_library from public, anon, authenticated;
grant select on public.hub_cards_library to authenticated, service_role;

-- ───────────────────────────────────────────── 5. audit (copy of 20261113100000 + the knowledge tables) ─────────────────────────────────────────────

__AUDIT_FN__

create trigger hub_knowledge_cards_audit after insert or update or delete on public.hub_knowledge_cards
  for each row execute function internal.audit('key', 'unit_keys', 'topic_keys', 'title_ar', 'title_en', 'text_ar', 'text_en', 'source', 'source_date',
                                               'expires_on', 'status', 'published_at', 'archived_at', 'faq_item_id', 'sort');
create trigger hub_topics_audit after insert or update or delete on public.hub_topics
  for each row execute function internal.audit('key', 'label_ar', 'label_en', 'parent_key', 'always_handoff', 'status', 'faq_keys');
-- never the excerpt (guest text): the queue's decisions only
create trigger hub_unanswered_audit after update on public.hub_unanswered
  for each row execute function internal.audit('status', 'topic_key', 'cluster_id', 'resolved_card_id', 'resolved_faq_id');

-- ───────────────────────────────────────────── 6. the seed (topics.json, knowledge-seed.json — 13 Nov 2026) ─────────────────────────────────────────────

-- topics.json (56, 9 always handed off), in the file's order; parents first
create temp table _topics on commit drop as
  select (t ->> 'key') as key, (t ->> 'label_ar') as label_ar, (t ->> 'label_en') as label_en, nullif(t ->> 'parent_key', '') as parent_key,
         coalesce((t ->> 'always_handoff')::boolean, false) as always_handoff, (o - 1)::integer as sort
    from jsonb_array_elements($seed_topics$__TOPICS_JSON__$seed_topics$::jsonb) with ordinality as x(t, o);
insert into public.hub_topics (key, label_ar, label_en, parent_key, always_handoff, sort)
select key, label_ar, label_en, null, always_handoff, sort from _topics;
update public.hub_topics h set parent_key = t.parent_key from _topics t where t.key = h.key and t.parent_key is not null;

-- which published FAQ question each topic reads (content/faq.json keys; the FAQ itself is read live)
update public.hub_topics h set faq_keys = m.keys
  from (values
    ('booking_new', array['confirmation']), ('booking_status', array['confirmation']), ('payment', array['payment']),
    ('cancellation_policy', array['cancellation']), ('occupancy', array['guests-extra-bed']), ('children', array['guests-extra-bed']),
    ('extra_bed', array['guests-extra-bed']), ('checkin_checkout', array['check-in-out', 'early-late']), ('early_late', array['early-late']),
    ('breakfast', array['breakfast']), ('documents', array['id']), ('wifi', array['wifi']), ('in_room_dining', array['dining-housekeeping']),
    ('housekeeping', array['dining-housekeeping']), ('house_rules', array['smoking', 'pets']), ('accessible', array['accessible']),
    ('parking', array['parking']), ('branch_info', array['branches']), ('branch_compare', array['branches']), ('reception_contact', array['contact']),
    ('distances', array['airport']), ('location_directions', array['airport', 'branches']), ('hall', array['hall']), ('groups_corporate', array['groups'])
  ) as m(key, keys)
 where h.key = m.key;

-- knowledge-seed.json (37 cards, approved by Ahmed on 13 Nov 2026): PUBLISHED as given, verified by the system admin
create temp table _cards on commit drop as
  select c, (o - 1)::integer as sort from jsonb_array_elements($seed_cards$__CARDS_JSON__$seed_cards$::jsonb) with ordinality as x(c, o);
do $$
declare
  v_admin uuid := (select s.user_id from public.staff s where s.role = 'admin' and s.active order by s.created_at limit 1);
  v_at timestamptz := '2026-11-13 12:00:00+03';
begin
  insert into public.hub_knowledge_cards (key, unit_keys, topic_keys, title_ar, title_en, text_ar, text_en, source, source_date, expires_on,
                                          verified_by, verified_at, status, sort, published_at, published_by, first_published_at, created_by, updated_by)
  select c ->> 'id', array(select jsonb_array_elements_text(c -> 'unit_keys')), array(select jsonb_array_elements_text(c -> 'topic_keys')),
         c ->> 'title_ar', c ->> 'title_en', c ->> 'text_ar', c ->> 'text_en', c ->> 'source', (c ->> 'source_date')::date, nullif(c ->> 'expires_on', '')::date,
         v_admin, v_at, 'draft', sort, v_at, v_admin, v_at, v_admin, v_admin
    from _cards order by sort;
  update public.hub_knowledge_cards k set live = internal.hub_card_snapshot(k), status = 'published' where k.key in (select c ->> 'id' from _cards);
end $$;

-- ───────────────────────────────────────────── 7. staff RPCs (knowledge: edit / publish) ─────────────────────────────────────────────

-- create (p_id null) or update a card. p = { key?, unit_keys, topic_keys, title_ar, title_en, text_ar, text_en, source,
-- source_date, expires_on, faq_item_id?, sort? }. A draft keeps what it holds (the check blocks «نشر» only); the key is
-- fixed once published; verified by = the saving user (shown in the editor).
create function public.hub_card_save(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_knowledge_cards;
  v_batch uuid;
  v_key text := lower(btrim(coalesce(p ->> 'key', '')));
  v_units text[];
  v_topics text[];
  v_src_date date;
  v_exp date;
begin
  if not internal.can('knowledge', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  if jsonb_typeof(coalesce(p -> 'unit_keys', '[]'::jsonb)) <> 'array' or jsonb_typeof(coalesce(p -> 'topic_keys', '[]'::jsonb)) <> 'array' then
    raise exception 'hub_card_fields' using errcode = '22023';
  end if;
  v_units := array(select distinct k from jsonb_array_elements_text(coalesce(p -> 'unit_keys', '[]'::jsonb)) k order by k);
  v_topics := array(select distinct k from jsonb_array_elements_text(coalesce(p -> 'topic_keys', '[]'::jsonb)) k order by k);
  if exists (select 1 from unnest(v_units) k where not exists (select 1 from public.hub_units u where u.key = k)) then raise exception 'hub_card_unit' using errcode = '22023'; end if;
  if exists (select 1 from unnest(v_topics) k where not exists (select 1 from public.hub_topics x where x.key = k and x.status <> 'archived')) then
    raise exception 'hub_card_topic' using errcode = '22023';
  end if;
  if char_length(coalesce(p ->> 'title_ar', '')) > 120 or char_length(coalesce(p ->> 'title_en', '')) > 120
     or char_length(coalesce(p ->> 'text_ar', '')) > 1200 or char_length(coalesce(p ->> 'text_en', '')) > 1200 or char_length(coalesce(p ->> 'source', '')) > 300 then
    raise exception 'hub_card_too_long' using errcode = '22023';
  end if;
  if btrim(coalesce(p ->> 'title_ar', '')) = '' and btrim(coalesce(p ->> 'title_en', '')) = '' then raise exception 'hub_card_title' using errcode = '22023'; end if;
  begin
    v_src_date := nullif(p ->> 'source_date', '')::date;
    v_exp := nullif(p ->> 'expires_on', '')::date;
  exception when others then
    raise exception 'hub_card_date' using errcode = '22023';
  end;
  if v_src_date is not null and v_src_date > internal.riyadh_today() then raise exception 'hub_card_source_future' using errcode = '22023'; end if;
  if p_id is not null then
    c := internal.hub_card_get(p_id, 'edit');
    if c.status = 'archived' then raise exception 'hub_card_archived' using errcode = '22023'; end if;
    if v_key = '' then v_key := c.key; end if;
    if c.key <> v_key and c.first_published_at is not null then raise exception 'hub_card_key_locked' using errcode = '22023'; end if;
  elsif v_key = '' then
    v_key := 'k-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10);
  end if;
  if v_key !~ '^k-[a-z0-9]+(-[a-z0-9]+)*$' or char_length(v_key) > 60 then raise exception 'hub_card_key' using errcode = '22023'; end if;
  if exists (select 1 from public.hub_knowledge_cards x where x.key = v_key and x.id is distinct from p_id) then raise exception 'hub_card_key_taken' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  if p_id is null then
    insert into public.hub_knowledge_cards (key, sort, created_by, updated_by)
    values (v_key, coalesce((select max(x.sort) + 1 from public.hub_knowledge_cards x), 0), auth.uid(), auth.uid())
    returning * into c;
  end if;
  update public.hub_knowledge_cards set key = v_key, unit_keys = v_units, topic_keys = v_topics,
         title_ar = btrim(coalesce(p ->> 'title_ar', '')), title_en = btrim(coalesce(p ->> 'title_en', '')),
         text_ar = btrim(coalesce(p ->> 'text_ar', '')), text_en = btrim(coalesce(p ->> 'text_en', '')),
         source = btrim(coalesce(p ->> 'source', '')), source_date = v_src_date, expires_on = v_exp,
         faq_item_id = case when p ? 'faq_item_id' then nullif(p ->> 'faq_item_id', '')::uuid else faq_item_id end,
         verified_by = auth.uid(), verified_at = now(), updated_by = auth.uid()
   where id = c.id returning * into c;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'id', c.id, 'key', c.key, 'check', internal.hub_card_check(c));
end;
$$;

-- «أرشفة»: out of every reply at once (only removing — never a new fact). A published card needs knowledge: publish.
-- «تراجع» = hub_card_restore.
create function public.hub_card_archive(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_knowledge_cards := internal.hub_card_get(p_id, 'edit');
  v_batch uuid;
begin
  if c.live is not null and not internal.can('knowledge', 'publish') then raise exception 'not allowed' using errcode = '42501'; end if;
  if c.status = 'archived' then return jsonb_build_object('ok', true, 'changed', false); end if;
  v_batch := internal.begin_batch();
  update public.hub_knowledge_cards set status = 'archived', archived_at = now(), archived_by = auth.uid(), updated_by = auth.uid() where id = c.id;
  return jsonb_build_object('ok', true, 'changed', true, 'batch_id', v_batch);
end;
$$;

-- «استرجاع»: back as it was — a card that was published returns with the text it was published with (already checked
-- and published once; a draft edit still waits for «نشر»); a never-published one returns as a draft.
create function public.hub_card_restore(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_knowledge_cards := internal.hub_card_get(p_id, 'edit');
  v_batch uuid;
begin
  if c.live is not null and not internal.can('knowledge', 'publish') then raise exception 'not allowed' using errcode = '42501'; end if;
  if c.status <> 'archived' then return jsonb_build_object('ok', true, 'changed', false); end if;
  v_batch := internal.begin_batch();
  update public.hub_knowledge_cards set status = case when live is null then 'draft' else 'published' end, archived_at = null, archived_by = null, updated_by = auth.uid()
   where id = c.id;
  return jsonb_build_object('ok', true, 'changed', true, 'batch_id', v_batch);
end;
$$;

-- the test-lab gate (spec §4.8) — session H6 replaces this function with the eval run on the candidate cards; until then
-- every publish passes it (no bank runs yet). One hook, called by hub_knowledge_publish with the cards about to go live.
create function internal.hub_knowledge_gate(p_cards uuid[]) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object('ok', true, 'gate', 'none', 'cards', cardinality(p_cards))
$$;

-- «نشر»: every pending card (drafts and edits) at once. Blocked while one has a problem (the list comes back), or by the
-- test-lab gate. Never undoable: edit and publish again.
create function public.hub_knowledge_publish(p_dry_run boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_blocked jsonb;
  v_ids uuid[];
  v_gate jsonb;
  v_batch uuid;
begin
  if not internal.can('knowledge', 'publish') then raise exception 'not allowed' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'key', c.key, 'title_ar', c.title_ar, 'missing', internal.hub_card_check(c) -> 'missing') order by c.sort), '[]'::jsonb)
    into v_blocked from public.hub_knowledge_cards c
   where (not c.is_test or internal.is_admin()) and internal.hub_card_pending(c) and jsonb_array_length(internal.hub_card_check(c) -> 'missing') > 0;
  if jsonb_array_length(v_blocked) > 0 then return jsonb_build_object('ok', false, 'reason', 'blocked', 'blocked', v_blocked); end if;
  v_ids := array(select c.id from public.hub_knowledge_cards c where (not c.is_test or internal.is_admin()) and internal.hub_card_pending(c) order by c.sort);
  if cardinality(v_ids) = 0 then return jsonb_build_object('ok', false, 'reason', 'nothing'); end if;
  v_gate := internal.hub_knowledge_gate(v_ids);
  if not coalesce((v_gate ->> 'ok')::boolean, false) then return jsonb_build_object('ok', false, 'reason', 'gate', 'gate', v_gate); end if;
  if p_dry_run then return jsonb_build_object('ok', true, 'dry_run', true, 'count', cardinality(v_ids)); end if;
  v_batch := internal.begin_batch();
  update public.hub_knowledge_cards c set live = internal.hub_card_snapshot(c), status = 'published', published_at = now(), published_by = auth.uid(),
         first_published_at = coalesce(c.first_published_at, now()), updated_by = auth.uid()
   where c.id = any (v_ids);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'count', cardinality(v_ids), 'gate', v_gate);
end;
$$;

-- ───────────────────────────────────────────── 8. «لم أعرف الإجابة» ─────────────────────────────────────────────

-- the words of a question, for grouping close wordings: Arabic letters unified (hamza forms, ta marbuta, alef maqsura),
-- marks and punctuation removed, «ال» and short / common words left out
create function internal.hub_words(p text) returns text[]
language sql immutable set search_path = '' as $$
  select coalesce(array_agg(distinct w), '{}') from (
    select regexp_replace(w, '^(ال|وال|بال|لل)(?=..)', '') as w
      from regexp_split_to_table(
             lower(translate(regexp_replace(coalesce(p, ''), '[ًٌٍَُِّْـ]', '', 'g'), 'أإآٱةى؟،؛', 'ااااهي   ')),
             '[^ء-يa-z0-9]+') w
  ) x
  where char_length(w) >= 2
    and w not in ('هل', 'في', 'من', 'على', 'عن', 'الى', 'او', 'ما', 'ماذا', 'كم', 'هو', 'هي', 'يا', 'لو', 'مع', 'عند', 'عندكم', 'لديكم', 'انا', 'ابي', 'ابغى',
                  'وش', 'اي', 'كيف', 'متى', 'فيه', 'فيها', 'هذا', 'هذه', 'ذلك', 'لكم', 'لي',
                  'the', 'is', 'are', 'do', 'does', 'you', 'have', 'there', 'can', 'what', 'how', 'when', 'where', 'for', 'and', 'or', 'of', 'to', 'in', 'at', 'it', 'my', 'me', 'an', 'any')
$$;

create function internal.hub_similar(a text[], b text[]) returns numeric
language sql immutable set search_path = '' as $$
  select case when cardinality(a) = 0 or cardinality(b) = 0 then 0
              else (select count(*) from (select unnest(a) intersect select unnest(b)) i)::numeric
                   / (select count(*) from (select unnest(a) union select unnest(b)) u)::numeric end
$$;

-- «المساعد لم يعرف» (H3, now with the queue): the message into «لم أعرف الإجابة» once, its excerpt kept (guest text, ≤ 300,
-- cleared after hub_retention_months), grouped with an OPEN entry of the same topic whose wording is close (≥ half the
-- words in common) — the cluster is the first entry's id and its count is times_asked
create or replace function public.hub_mark_unanswered(p_message uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  m public.hub_messages;
  c public.hub_conversations;
  v_id uuid;
  v_excerpt text;
  v_root uuid;
begin
  select * into m from public.hub_messages where id = p_message;
  if m.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  c := internal.hub_conv_edit(m.conversation_id);
  if m.direction <> 'in' or m.author <> 'guest' then raise exception 'hub_unanswered_guest_only' using errcode = '22023'; end if;
  v_excerpt := nullif(left(btrim(regexp_replace(coalesce(m.body, ''), '\s+', ' ', 'g')), 300), '');
  insert into public.hub_unanswered (unit_id, conversation_id, message_id, marked_by, question_excerpt, is_test)
  values (c.unit_id, c.id, m.id, auth.uid(), v_excerpt, c.is_test)
  on conflict (message_id) do nothing
  returning id into v_id;
  if v_id is null then return jsonb_build_object('ok', true, 'changed', false); end if;
  select r.id into v_root from public.hub_unanswered r
   where r.status = 'open' and r.id = r.cluster_id and r.id <> v_id and r.is_test = c.is_test
     and internal.hub_similar(internal.hub_words(r.question_excerpt), internal.hub_words(v_excerpt)) >= 0.5
   order by internal.hub_similar(internal.hub_words(r.question_excerpt), internal.hub_words(v_excerpt)) desc, r.created_at
   limit 1 for update;
  if v_root is null then
    update public.hub_unanswered set cluster_id = id where id = v_id;
  else
    update public.hub_unanswered set cluster_id = v_root, topic_key = (select x.topic_key from public.hub_unanswered x where x.id = v_root) where id = v_id;
    update public.hub_unanswered set times_asked = (select count(*) from public.hub_unanswered x where x.cluster_id = v_root and x.status = 'open') where id = v_root;
  end if;
  insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, actor_staff_id, reason, is_test)
  values (c.id, 'unanswered', null, 'open', auth.uid(), 'staff', c.is_test);
  return jsonb_build_object('ok', true, 'changed', true, 'id', v_id, 'cluster_id', coalesce(v_root, v_id));
end;
$$;

-- a topic for a whole cluster (knowledge: edit); the cluster then joins an open cluster of that topic and close wording
create function public.hub_unanswered_topic_set(p_id uuid, p_topic text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.hub_unanswered;
  v_batch uuid;
  v_root uuid;
  v_target uuid;
begin
  if not internal.can('knowledge', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into r from public.hub_unanswered where id = p_id for update;
  if r.id is null or r.status <> 'open' or (r.is_test and not internal.is_admin()) then raise exception 'not_found' using errcode = '22023'; end if;
  if p_topic is not null and not exists (select 1 from public.hub_topics t where t.key = p_topic and t.status <> 'archived') then raise exception 'hub_card_topic' using errcode = '22023'; end if;
  v_root := coalesce(r.cluster_id, r.id);
  select x.id into v_target from public.hub_unanswered x
   where x.status = 'open' and x.id = x.cluster_id and x.id <> v_root and x.is_test = r.is_test and x.topic_key is not distinct from p_topic
     and internal.hub_similar(internal.hub_words(x.question_excerpt), internal.hub_words((select y.question_excerpt from public.hub_unanswered y where y.id = v_root))) >= 0.5
   order by x.created_at limit 1;
  v_batch := internal.begin_batch();
  update public.hub_unanswered set topic_key = p_topic, cluster_id = coalesce(v_target, v_root) where cluster_id = v_root and status = 'open';
  if v_target is not null then
    update public.hub_unanswered set times_asked = (select count(*) from public.hub_unanswered x where x.cluster_id = v_target and x.status = 'open') where id = v_target;
  end if;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'cluster_id', coalesce(v_target, v_root));
end;
$$;

-- resolve a cluster (every OPEN entry of it): p = { action: card | faq | both | dismiss, card_id (card / both),
-- faq: {category, q_ar, q_en, a_ar, a_en} (faq / both — a DRAFT in «الأسئلة الشائعة», published there by its own «نشر»;
-- content: edit) }. Never the guest's words in the card or the FAQ: the editor writes them.
create function public.hub_unanswered_resolve(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.hub_unanswered;
  v_action text := coalesce(p ->> 'action', '');
  v_card uuid;
  v_faq uuid;
  v_root uuid;
  v_batch uuid;
  v_n integer;
  f jsonb := coalesce(p -> 'faq', '{}'::jsonb);
begin
  if not internal.can('knowledge', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  if v_action not in ('card', 'faq', 'both', 'dismiss') then raise exception 'hub_resolve_action' using errcode = '22023'; end if;
  select * into r from public.hub_unanswered where id = p_id for update;
  if r.id is null or (r.is_test and not internal.is_admin()) then raise exception 'not_found' using errcode = '22023'; end if;
  if r.status <> 'open' then raise exception 'hub_resolve_done' using errcode = '22023'; end if;
  v_root := coalesce(r.cluster_id, r.id);
  if v_action in ('card', 'both') then
    v_card := nullif(p ->> 'card_id', '')::uuid;
    if v_card is null or not exists (select 1 from public.hub_knowledge_cards k where k.id = v_card and k.status <> 'archived' and (not k.is_test or internal.is_admin())) then
      raise exception 'hub_resolve_card' using errcode = '22023';
    end if;
  end if;
  v_batch := internal.begin_batch();
  if v_action in ('faq', 'both') then
    if not internal.can('content', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
    if coalesce(f ->> 'category', '') not in ('booking', 'stay', 'branches', 'business') then raise exception 'faq_category' using errcode = '22023'; end if;
    if char_length(coalesce(f ->> 'q_ar', '')) > 400 or char_length(coalesce(f ->> 'q_en', '')) > 400
       or char_length(coalesce(f ->> 'a_ar', '')) > 3000 or char_length(coalesce(f ->> 'a_en', '')) > 3000 then
      raise exception 'faq_too_long' using errcode = '22023';
    end if;
    if btrim(coalesce(f ->> 'q_ar', '')) = '' and btrim(coalesce(f ->> 'q_en', '')) = '' then raise exception 'faq_question' using errcode = '22023'; end if;
    insert into public.faq_items (key, category, q_ar, q_en, a_ar, a_en, sort, created_by, updated_by, is_test)
    values ('hub-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8), f ->> 'category',
            btrim(coalesce(f ->> 'q_ar', '')), btrim(coalesce(f ->> 'q_en', '')), btrim(coalesce(f ->> 'a_ar', '')), btrim(coalesce(f ->> 'a_en', '')),
            coalesce((select max(x.sort) + 1 from public.faq_items x), 0), auth.uid(), auth.uid(), r.is_test)
    returning id into v_faq;
    if v_card is not null then update public.hub_knowledge_cards set faq_item_id = v_faq, updated_by = auth.uid() where id = v_card; end if;
  end if;
  update public.hub_unanswered
     set status = case when v_action = 'dismiss' then 'dismissed' else 'answered' end,
         resolved_card_id = v_card, resolved_faq_id = v_faq, resolved_by = auth.uid(), resolved_at = now()
   where cluster_id = v_root and status = 'open';
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'count', v_n, 'card_id', v_card, 'faq_id', v_faq);
end;
$$;

-- the queue, one row per cluster (knowledge: view). The excerpts are guest text: shown only from entries whose unit the
-- caller may read (internal.can_unit — the inbox scope); otherwise the count, the topic and the units only.
create function public.hub_unanswered_list(p_status text default 'open') returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_rows jsonb;
begin
  if not internal.can('knowledge', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_status not in ('open', 'answered', 'dismissed') then raise exception 'hub_status' using errcode = '22023'; end if;
  select coalesce(jsonb_agg(x order by x ->> 'last_at' desc), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
             'id', g.cluster_id, 'count', count(*), 'topic_key', max(g.topic_key),
             'topic_label', (select t.label_ar from public.hub_topics t where t.key = max(g.topic_key)),
             'first_at', min(g.created_at), 'last_at', max(g.created_at),
             'units', (select jsonb_agg(distinct coalesce(v.name_ar, u.name_ar)) from public.hub_unanswered y join public.hub_units u on u.id = y.unit_id
                        left join public.dining_venues v on v.id = u.dining_venue_id where y.cluster_id = g.cluster_id and y.status = p_status),
             'excerpts', coalesce((select jsonb_agg(e) from (select distinct y.question_excerpt as e from public.hub_unanswered y
                                    where y.cluster_id = g.cluster_id and y.status = p_status and y.question_excerpt is not null and internal.can_unit(y.unit_id, 'view')
                                    limit 3) z), '[]'::jsonb),
             'hidden_excerpts', count(*) filter (where g.question_excerpt is not null and not internal.can_unit(g.unit_id, 'view')),
             'resolved_card_id', max(g.resolved_card_id::text), 'resolved_faq_id', max(g.resolved_faq_id::text), 'resolved_at', max(g.resolved_at),
             'is_test', bool_or(g.is_test)) as x
      from public.hub_unanswered g
     where g.status = p_status and (not g.is_test or internal.is_admin())
     group by g.cluster_id
     limit 500) q;
  return jsonb_build_object('rows', v_rows,
    'open', (select count(distinct y.cluster_id) from public.hub_unanswered y where y.status = 'open' and (not y.is_test or internal.is_admin())));
end;
$$;

-- ───────────────────────────────────────────── 9. reads for «قاعدة المعرفة» and «أسعار الخدمات» ─────────────────────────────────────────────

-- the published FAQ as the engine reads it (read-only tab «الأسئلة الشائعة»): every published, shown question, the fees
-- filled from Settings, and the topics that read it
create function public.hub_knowledge_faq() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('knowledge', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'key', f.key, 'category', f.live ->> 'category',
             'q_ar', f.live ->> 'q_ar', 'q_en', f.live ->> 'q_en',
             'a_ar', internal.hub_fill_fees(f.live ->> 'a_ar', 'ar'), 'a_en', internal.hub_fill_fees(f.live ->> 'a_en', 'en'),
             'published_at', f.published_at, 'pending', internal.faq_pending(f),
             'topics', coalesce((select jsonb_agg(t.key order by t.sort) from public.hub_topics t where f.key = any (t.faq_keys) and t.status = 'active'), '[]'::jsonb))
           order by array_position(array['booking', 'stay', 'branches', 'business'], f.live ->> 'category'), (f.live ->> 'sort')::int, f.key)
    from public.faq_items f
   where f.live is not null and not coalesce((f.live ->> 'hidden')::boolean, false) and not f.is_test), '[]'::jsonb);
end;
$$;

-- «أسعار الخدمات» (spec §4.4 / §5.5, read-only): the fees kept in Settings (breakfast per adult and the child tiers, the
-- extra bed). Late check-out and the lost key card are content/policies.json (the dashboard reads the file).
create function public.hub_service_prices() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('knowledge', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'breakfast', (select s.value from public.settings s where s.key = 'breakfast'),
    'extra_bed_per_night', (select (s.value #>> '{}')::numeric from public.settings s where s.key = 'extra_bed_per_night'),
    'fees', public.site_fees());
end;
$$;

-- what ends soon (the «تنتهي قريبًا» tab and the daily alert): published cards ending within hub_card_expiry_alert_days
-- and published offers ending within hub_offer_expiry_alert_days (Riyadh dates; today included)
create function internal.hub_expiring_items(p_today date) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select jsonb_agg(x order by x ->> 'ends', x ->> 'kind', x ->> 'title') from (
    select jsonb_build_object('kind', 'card', 'id', c.id, 'key', c.key, 'title', c.live ->> 'title_ar', 'ends', (c.live ->> 'expires_on')::date, 'is_test', c.is_test) as x
      from public.hub_knowledge_cards c
     where c.status = 'published' and c.live is not null and (c.live ->> 'expires_on') is not null
       and (c.live ->> 'expires_on')::date between p_today and p_today + internal.hub_setting_int('hub_card_expiry_alert_days', 14)
    union all
    select jsonb_build_object('kind', 'offer', 'id', o.id, 'key', o.slug, 'title', o.live ->> 'title_ar', 'ends', (o.live ->> 'valid_to')::date, 'is_test', o.is_test)
      from public.offers o
     where o.live is not null and o.archived_at is null and (o.live ->> 'valid_to') is not null
       and (o.live ->> 'valid_to')::date between p_today and p_today + internal.hub_setting_int('hub_offer_expiry_alert_days', 7)) q), '[]'::jsonb)
$$;

create function public.hub_expiring() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('knowledge', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object('today', internal.riyadh_today(), 'card_days', internal.hub_setting_int('hub_card_expiry_alert_days', 14),
                            'offer_days', internal.hub_setting_int('hub_offer_expiry_alert_days', 7),
                            'items', coalesce((select jsonb_agg(e) from jsonb_array_elements(internal.hub_expiring_items(internal.riyadh_today())) e
                                                where not (e ->> 'is_test')::boolean or internal.is_admin()), '[]'::jsonb));
end;
$$;

-- ───────────────────────────────────────────── 10. the engine's read (service role only) ─────────────────────────────────────────────

-- hub_knowledge_for(unit key, topics, language) — what compose receives for one turn (spec §4.6):
--   cards: at most hub_cards_per_turn published, unexpired cards sharing a topic (or a topic's parent / child) with the
--          turn; never one tagged with a knowledge_hidden unit; a card tagged with units is read only on those units'
--          numbers (a dining unit also reads its branch's); the unit's own cards first (tagged with it alone), then the
--          shared ones (tagged with it among others), then the untagged; then exact topic matches, then the order.
--   faq:   the published FAQ questions those topics read (hub_topics.faq_keys), read live, the fees filled from Settings,
--          at most hub_cards_per_turn.
-- The rooftop unit (knowledge_hidden) reads nothing.
create function public.hub_knowledge_for(p_unit text, p_topics text[], p_language text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_keys text[];
  v_hidden text[] := array(select x.key from public.hub_units x where x.knowledge_hidden);
  v_rel text[];
  v_n integer := greatest(internal.hub_setting_int('hub_cards_per_turn', 5), 1);
  v_lang text := case when p_language = 'en' then 'en' else 'ar' end;
  v_today date := internal.riyadh_today();
  v_cards jsonb;
  v_faq jsonb;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  if u.knowledge_hidden or cardinality(coalesce(p_topics, '{}')) = 0 then
    return jsonb_build_object('unit', u.key, 'language', v_lang, 'cards', '[]'::jsonb, 'faq', '[]'::jsonb);
  end if;
  v_keys := array[u.key] || case when u.kind = 'dining' then array(select b.key from public.hub_units b where b.kind = 'branch' and b.branch_slug = u.branch_slug) else '{}' end;
  -- a topic's parent and its children count as related
  v_rel := array(select t.parent_key from public.hub_topics t where t.key = any (p_topics) and t.parent_key is not null
                 union select t.key from public.hub_topics t where t.parent_key = any (p_topics));
  select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'key', z.key, 'title', z.live ->> ('title_' || v_lang), 'text', z.live ->> ('text_' || v_lang),
                                               'source', z.live ->> 'source', 'source_date', z.live ->> 'source_date', 'unit_keys', z.live -> 'unit_keys',
                                               'topic_keys', z.live -> 'topic_keys') order by z.rank_unit, z.exact desc, z.related desc, z.sort, z.key), '[]'::jsonb)
    into v_cards from (
      select c.id, c.key, c.live, c.sort,
             case when c.unit_keys = array[u.key] then 0 when u.key = any (c.unit_keys) then 1 when c.unit_keys && v_keys then 2 else 3 end as rank_unit,
             (select count(*) from unnest(c.topic_keys) k where k = any (p_topics)) as exact,
             (select count(*) from unnest(c.topic_keys) k where k = any (v_rel)) as related
        from (select k.id, k.key, k.live, k.sort, array(select jsonb_array_elements_text(k.live -> 'unit_keys')) as unit_keys,
                     array(select jsonb_array_elements_text(k.live -> 'topic_keys')) as topic_keys
                from public.hub_knowledge_cards k
               where k.status = 'published' and k.live is not null and not k.is_test
                 and ((k.live ->> 'expires_on') is null or (k.live ->> 'expires_on')::date >= v_today)) c
       where not (c.unit_keys && v_hidden)
         and (cardinality(c.unit_keys) = 0 or c.unit_keys && v_keys)
         and (c.topic_keys && p_topics or c.topic_keys && v_rel)
       order by rank_unit, exact desc, related desc, c.sort, c.key
       limit v_n) z;
  select coalesce(jsonb_agg(jsonb_build_object('key', z.key, 'q', z.live ->> ('q_' || v_lang), 'a', internal.hub_fill_fees(z.live ->> ('a_' || v_lang), v_lang))
                            order by z.hits desc, z.sort, z.key), '[]'::jsonb)
    into v_faq from (
      select y.* from (
        select f.key, f.live, (f.live ->> 'sort')::int as sort,
               (select count(*) from public.hub_topics t where t.key = any (p_topics) and f.key = any (t.faq_keys)) * 2
               + (select count(*) from public.hub_topics t where t.key = any (v_rel) and f.key = any (t.faq_keys)) as hits
          from public.faq_items f
         where f.live is not null and not coalesce((f.live ->> 'hidden')::boolean, false) and not f.is_test) y
       where y.hits > 0
       order by y.hits desc, y.sort, y.key
       limit v_n) z;
  return jsonb_build_object('unit', u.key, 'language', v_lang, 'cards', v_cards, 'faq', v_faq);
end;
$$;

-- ───────────────────────────────────────────── 11. the expiry alerts (pg_cron hub-expiry, daily) ─────────────────────────────────────────────

-- one hub_alerts row per item ending soon (kind card_expiring / offer_ending; payload: the item, the kind, the end date —
-- no text); an alert whose item left the window (extended, archived, ended) is closed; when a NEW one appeared,
-- wa-automation (hub-expiry) is asked to send the one email
create function public.hub_expiry_tick(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_items jsonb := internal.hub_expiring_items(internal.riyadh_today(p_now));
  v_new integer;
  v_closed integer;
  v_req bigint;
  v_url text;
  v_token text;
begin
  perform set_config('app.actor', 'hub', true);
  with i as (select e from jsonb_array_elements(v_items) e where not (e ->> 'is_test')::boolean)
  update public.hub_alerts a set acknowledged_at = p_now
   where a.kind in ('card_expiring', 'offer_ending') and a.acknowledged_at is null and not a.is_test
     and not exists (select 1 from i where i.e ->> 'id' = a.payload ->> 'item' and i.e ->> 'ends' = a.payload ->> 'ends');
  get diagnostics v_closed = row_count;
  insert into public.hub_alerts (kind, payload)
  select case e ->> 'kind' when 'card' then 'card_expiring' else 'offer_ending' end,
         jsonb_build_object('item', e ->> 'id', 'type', e ->> 'kind', 'ends', e ->> 'ends')
    from jsonb_array_elements(v_items) e where not (e ->> 'is_test')::boolean
  on conflict do nothing;
  get diagnostics v_new = row_count;
  if exists (select 1 from public.hub_alerts a where a.kind in ('card_expiring', 'offer_ending') and a.acknowledged_at is null and a.sent_at is null and not a.is_test) then
    v_url := internal.vault_value('job_sweep_url');
    v_token := internal.vault_value('wa_cron_token');
    if coalesce(v_url, '') <> '' and coalesce(v_token, '') <> '' and v_url ~ '/functions/v1/' then
      v_req := net.http_post(
        url := regexp_replace(v_url, '/functions/v1/.*$', '/functions/v1/wa-automation'),
        body := jsonb_build_object('action', 'hub-expiry'),
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-armada-cron', v_token),
        timeout_milliseconds := 30000);
    end if;
  end if;
  return jsonb_build_object('ok', true, 'items', jsonb_array_length(v_items), 'new', v_new, 'closed', v_closed, 'request', v_req);
end;
$$;

-- the email's list (service role — wa-automation hub-expiry): when an open expiry alert was not yet emailed, every open one
-- (the whole «تنتهي قريبًا» list) with its title and date, the active admins' addresses; the unsent ones are marked sent
-- at once (claimed once). Empty list → no email.
create function public.hub_expiry_claim(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_to text[] := public.site_deploy_alert_recipients();
  v_items jsonb;
begin
  if not exists (select 1 from public.hub_alerts a where a.kind in ('card_expiring', 'offer_ending') and a.acknowledged_at is null and a.sent_at is null and not a.is_test) then
    return jsonb_build_object('items', '[]'::jsonb, 'recipients', '[]'::jsonb);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('type', a.payload ->> 'type', 'ends', a.payload ->> 'ends',
           'title', case a.kind when 'card_expiring' then (select c.live ->> 'title_ar' from public.hub_knowledge_cards c where c.id::text = a.payload ->> 'item')
                                else (select o.live ->> 'title_ar' from public.offers o where o.id::text = a.payload ->> 'item') end)
           order by a.payload ->> 'ends', a.kind), '[]'::jsonb)
    into v_items from public.hub_alerts a where a.kind in ('card_expiring', 'offer_ending') and a.acknowledged_at is null and not a.is_test;
  update public.hub_alerts set sent_at = p_now, sent_to = v_to
   where kind in ('card_expiring', 'offer_ending') and acknowledged_at is null and sent_at is null and not is_test;
  return jsonb_build_object('items', v_items, 'recipients', to_jsonb(v_to), 'date', internal.riyadh_today(p_now));
end;
$$;

select cron.schedule('hub-expiry', '0 5 * * *', 'select public.hub_expiry_tick()');

-- ───────────────────────────────────────────── 12. retention (copy of 20261113200000 + the queue's excerpts) ─────────────────────────────────────────────

create or replace function public.hub_retention(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_months integer := internal.hub_setting_int('hub_retention_months', 12);
  v_days integer := internal.hub_setting_int('hub_media_retention_days', 90);
  v_texts integer;
  v_media integer;
  v_excerpts integer;
  v_pending integer;
  v_req bigint;
  v_url text := internal.vault_value('job_sweep_url');
  v_token text := internal.vault_value('wa_cron_token');
begin
  perform set_config('app.actor', 'retention', true);
  update public.hub_messages
     set body = null, translation_ar = null, translation_en = null, purged_at = p_now
   where purged_at is null and created_at < p_now - make_interval(months => v_months);
  get diagnostics v_texts = row_count;
  update public.hub_messages set media_pending_delete = true
   where media_path is not null and not media_pending_delete and created_at < p_now - make_interval(days => v_days);
  get diagnostics v_media = row_count;
  -- H4: «لم أعرف الإجابة» keeps the question's words for the same 12 months
  update public.hub_unanswered set question_excerpt = null
   where question_excerpt is not null and created_at < p_now - make_interval(months => v_months);
  get diagnostics v_excerpts = row_count;
  select count(*) into v_pending from public.hub_messages where media_pending_delete;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (null, 'retention', 'hub_retention', to_char(p_now at time zone 'Asia/Riyadh', 'YYYY-MM-DD'), null, 'update', null,
          jsonb_build_object('texts', v_texts, 'media', v_media, 'excerpts', v_excerpts, 'months', v_months, 'days', v_days), gen_random_uuid());
  if v_pending > 0 and coalesce(v_url, '') <> '' and coalesce(v_token, '') <> '' and v_url ~ '/functions/v1/' then
    v_req := net.http_post(
      url := regexp_replace(v_url, '/functions/v1/.*$', '/functions/v1/wa-automation'),
      body := jsonb_build_object('action', 'hub-media-purge'),
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-armada-cron', v_token),
      timeout_milliseconds := 60000);
  end if;
  return jsonb_build_object('ok', true, 'texts', v_texts, 'media', v_media, 'excerpts', v_excerpts, 'pending', v_pending, 'request', v_req);
end;
$$;

-- ───────────────────────────────────────────── 13. grants ─────────────────────────────────────────────

revoke execute on function internal.hub_forbidden_terms(), internal.hub_known_phones(), internal.hub_without_known_phones(text),
  internal.hub_card_snapshot(public.hub_knowledge_cards), internal.hub_card_pending(public.hub_knowledge_cards), internal.hub_card_check(public.hub_knowledge_cards),
  internal.hub_card_get(uuid, public.perm_level), internal.riyadh_today(timestamptz), internal.hub_sar_text(numeric, text), internal.hub_fill_fees(text, text),
  internal.hub_knowledge_gate(uuid[]), internal.hub_words(text), internal.hub_similar(text[], text[]), internal.hub_expiring_items(date) from public, anon;
grant execute on function internal.hub_forbidden_terms(), internal.hub_known_phones(), internal.hub_without_known_phones(text),
  internal.hub_card_snapshot(public.hub_knowledge_cards), internal.hub_card_pending(public.hub_knowledge_cards), internal.hub_card_check(public.hub_knowledge_cards),
  internal.riyadh_today(timestamptz), internal.hub_sar_text(numeric, text), internal.hub_fill_fees(text, text), internal.hub_words(text), internal.hub_similar(text[], text[])
  to authenticated, service_role;
grant execute on function internal.hub_card_get(uuid, public.perm_level), internal.hub_knowledge_gate(uuid[]), internal.hub_expiring_items(date) to service_role;

revoke execute on function public.hub_card_save(uuid, jsonb), public.hub_card_archive(uuid), public.hub_card_restore(uuid), public.hub_knowledge_publish(boolean),
  public.hub_unanswered_topic_set(uuid, text), public.hub_unanswered_resolve(uuid, jsonb), public.hub_unanswered_list(text), public.hub_knowledge_faq(),
  public.hub_service_prices(), public.hub_expiring(), public.hub_mark_unanswered(uuid) from public, anon;
grant execute on function public.hub_card_save(uuid, jsonb), public.hub_card_archive(uuid), public.hub_card_restore(uuid), public.hub_knowledge_publish(boolean),
  public.hub_unanswered_topic_set(uuid, text), public.hub_unanswered_resolve(uuid, jsonb), public.hub_unanswered_list(text), public.hub_knowledge_faq(),
  public.hub_service_prices(), public.hub_expiring(), public.hub_mark_unanswered(uuid) to authenticated, service_role;

revoke execute on function public.hub_knowledge_for(text, text[], text), public.hub_expiry_tick(timestamptz), public.hub_expiry_claim(timestamptz),
  public.hub_retention(timestamptz) from public, anon, authenticated;
grant execute on function public.hub_knowledge_for(text, text[], text), public.hub_expiry_tick(timestamptz), public.hub_expiry_claim(timestamptz),
  public.hub_retention(timestamptz) to service_role;
